UPDATE public.blog_posts SET title_ar='دليل الامتثال للقانون PDPL المصري (القانون رقم 151 لسنة 2020) لعام 2026: أمن المستندات لشركات القاهرة', excerpt_ar='شرح قانون حماية البيانات الشخصية المصري رقم 151 لسنة 2020 لأصحاب الأعمال — غرامات تصل إلى 5 ملايين جنيه مصري، وقواعد توطين البيانات، وإخطارات خرق البيانات، وخطة عملية للاستعداد خلال 30 يومًا.' WHERE slug='egypt-pdpl-law-151-2020-compliance-guide';